export const PREF_KEY='chemlab_preferences_v1';
export function normalizePreferences(raw){return {cityEnabled:raw?.cityEnabled!==false,calm:raw?.calm===true};}
export function readPreferences(storage=localStorage){try{return normalizePreferences(JSON.parse(storage.getItem(PREF_KEY)))}catch{return normalizePreferences()}}
export const SAVE_KEYS=['chemlab_v50','chemlab_settlement_v2','chemlab_expansion_v1','chemlab_world_v1',PREF_KEY,'chemlab_sound','chemlab_cosmetic','chemlab_tutorial_v1'];
export function makeBackup(storage){const values={};for(let i=0;i<storage.length;i++){const k=storage.key(i);if(k?.startsWith('chemlab_'))values[k]=storage.getItem(k)}return {game:'ChemLab',version:1,created:new Date().toISOString(),values};}
export function validateBackup(data){if(data?.game!=='ChemLab'||data.version!==1||!data.values||typeof data.values!=='object'||Array.isArray(data.values))throw Error('Це не резервна копія ChemLab.');const out={};for(const [k,v]of Object.entries(data.values)){if(!/^chemlab_[a-zA-Z0-9_]+$/.test(k)||typeof v!=='string'||v.length>2000000)throw Error('Некоректний формат збереження.');out[k]=v;}if(!out.chemlab_v50)throw Error('У файлі немає прогресу лабораторії.');const core=JSON.parse(out.chemlab_v50);if(!Number.isInteger(core.level)||core.level<1||core.level>100000)throw Error('Некоректний рівень лабораторії.');if(out.chemlab_settlement_v2){const c=JSON.parse(out.chemlab_settlement_v2);if(c.version!==1||!Array.isArray(c.buildings))throw Error('Некоректний прогрес міста.');}return out;}
export function restoreBackup(data,storage){const values=validateBackup(data),old={};for(const k of Object.keys(values))old[k]=storage.getItem(k);try{for(const [k,v]of Object.entries(values))storage.setItem(k,v)}catch(error){for(const [k,v]of Object.entries(old)){try{if(v===null)storage.removeItem(k);else storage.setItem(k,v)}catch{}}throw error;}}
